            let provider = root.appendingPathComponent("provider/fixture")
            try FileManager.default.createDirectory(at: provider, withIntermediateDirectories: true)
            try rows.write(to: provider.appendingPathComponent("Rows.class"))
            let consumer = """
            import fixture.Rows
            import androidx.compose.runtime.Composable

            @Composable fun Row(index: Int) { println(index) }

            fun Rows.Show() {
                rows(2) { index -> Row(index) }
                this.rows(count = 1, start = 7) { index -> Row(index) }
            }
